import{_ as e,o as l,c as r,ae as t}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"雲端備份與同步說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/06-cloud-backup-guide.md","filePath":"v1/zh-HK/guide/06-cloud-backup-guide.md"}'),i={name:"v1/zh-HK/guide/06-cloud-backup-guide.md"};function o(h,a,n,u,d,p){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="雲端備份與同步說明" tabindex="-1">雲端備份與同步說明 <a class="header-anchor" href="#雲端備份與同步說明" aria-label="Permalink to &quot;雲端備份與同步說明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>雲端備份可把你的資料同步到雲端，方便多裝置使用與資料復原。</p><hr><h2 id="☁️-什麼是雲端備份" tabindex="-1">☁️ 什麼是雲端備份？ <a class="header-anchor" href="#☁️-什麼是雲端備份" aria-label="Permalink to &quot;☁️ 什麼是雲端備份？&quot;">​</a></h2><p>雲端備份會把資料保存到雲端伺服器，帶來：</p><ul><li><strong>資料安全</strong>：降低裝置遺失/損壞造成資料遺失的風險</li><li><strong>多裝置同步</strong>：同一帳號在不同裝置上使用可同步資料</li><li><strong>資料復原</strong>：更換新裝置後登入即可重新同步資料</li></ul><blockquote><p>💡 提示：</p><ul><li>雲端備份需要登入帳號。</li><li>系統會做資料隔離與存取控制，確保只有你能存取自己的資料。</li></ul></blockquote><h2 id="🔐-登入" tabindex="-1">🔐 登入 <a class="header-anchor" href="#🔐-登入" aria-label="Permalink to &quot;🔐 登入&quot;">​</a></h2><p>目前支援 Apple 登入：在設定頁頂部點使用者卡片 → 使用 Apple 登入。</p><hr><h2 id="🔄-同步方式" tabindex="-1">🔄 同步方式 <a class="header-anchor" href="#🔄-同步方式" aria-label="Permalink to &quot;🔄 同步方式&quot;">​</a></h2><ul><li>自動同步：通常會在 App 啟動、資料變更後、切換帳本時自動同步</li><li>手動同步：設定頁右上角點雲朵圖示</li></ul><blockquote><p>⚠️ 注意：手動同步時請保持 App 在前台運行，直到同步完成。</p></blockquote><h2 id="📊-會同步什麼" tabindex="-1">📊 會同步什麼？ <a class="header-anchor" href="#📊-會同步什麼" aria-label="Permalink to &quot;📊 會同步什麼？&quot;">​</a></h2><p>會同步：帳本、帳單、帳戶、分類、標籤<br> 不會同步：App 設定（主題/語言）、快取、偏好設定</p><hr><h2 id="📌-同步狀態-概念" tabindex="-1">📌 同步狀態（概念） <a class="header-anchor" href="#📌-同步狀態-概念" aria-label="Permalink to &quot;📌 同步狀態（概念）&quot;">​</a></h2><p>資料通常會有類似以下狀態：</p><ul><li>已同步</li><li>待同步（有變更尚未同步）</li><li>待刪除（已刪除，等待同步到雲端）</li></ul><hr><h2 id="🔄-衝突處理-多裝置同時修改" tabindex="-1">🔄 衝突處理（多裝置同時修改） <a class="header-anchor" href="#🔄-衝突處理-多裝置同時修改" aria-label="Permalink to &quot;🔄 衝突處理（多裝置同時修改）&quot;">​</a></h2><p>若多裝置同時修改同一筆資料，系統會盡量保留最新修改，並避免把尚未同步的本機修改被雲端覆蓋。</p><hr><p><strong>最後更新</strong>：2026 年 5 月</p>',25)])])}const b=e(i,[["render",o]]);export{c as __pageData,b as default};
